// Extracted dual-eye animations from iPixel Color APK (assets/remote/ipixel_rc_eye_anim_*).
// Each frame represents symmetric left + right 32x16 eyes positioned on a 96x16 canvas.
import { Bitmap } from "./bitmap.js";
import { COLS, ROWS } from "./protocol.js";

export const APK_EYES_META = [{'num': 1, 'mode': 'apk_beast_red', 'label': 'Devil Beast', 'hint': 'Dual demon glare', 'icon': '🔥', 'color': '#ef4444', 'start': 0, 'count': 65}, {'num': 2, 'mode': 'apk_predator_gold', 'label': 'Gold Predator', 'hint': 'Amber hunt eyes', 'icon': '🦁', 'color': '#f59e0b', 'start': 8320, 'count': 65}, {'num': 3, 'mode': 'apk_hunter_cyan', 'label': 'Cyber Hunter', 'hint': 'Ice blue gaze', 'icon': '🧊', 'color': '#06b6d4', 'start': 16640, 'count': 65}, {'num': 4, 'mode': 'apk_demon_crimson', 'label': 'Crimson Demon', 'hint': 'Fierce red glow', 'icon': '👹', 'color': '#dc2626', 'start': 24960, 'count': 97}, {'num': 5, 'mode': 'apk_visor_teal', 'label': 'Neon Visor', 'hint': 'Cyber optic dual', 'icon': '🤖', 'color': '#14b8a6', 'start': 37376, 'count': 97}, {'num': 6, 'mode': 'apk_viper_green', 'label': 'Emerald Viper', 'hint': 'Venom slit eyes', 'icon': '🐍', 'color': '#10b981', 'start': 49792, 'count': 97}, {'num': 7, 'mode': 'apk_phantom_blood', 'label': 'Blood Phantom', 'hint': 'Deep sinister glare', 'icon': '🩸', 'color': '#b91c1c', 'start': 62208, 'count': 102}, {'num': 8, 'mode': 'apk_hawk_amber', 'label': 'Golden Hawk', 'hint': 'Sharp predator slit', 'icon': '🦅', 'color': '#d97706', 'start': 75264, 'count': 102}, {'num': 9, 'mode': 'apk_specter_cyan', 'label': 'Electric Specter', 'hint': 'Neon spirit gaze', 'icon': '⚡', 'color': '#0891b2', 'start': 88320, 'count': 102}];

const APK_EYES_BY_MODE = Object.fromEntries(APK_EYES_META.map((m) => [m.mode, m]));

const EYES_B64 = "";

let decodedData = null;
function getData() {
  if (!decodedData) {
    const bin = atob(EYES_B64);
    const len = bin.length;
    const u8 = new Uint8Array(len);
    for (let i = 0; i < len; i++) u8[i] = bin.charCodeAt(i);
    decodedData = u8;
  }
  return decodedData;
}

export function isApkEye(mode) {
  return Boolean(APK_EYES_BY_MODE[mode]);
}

export function getApkEyeBitmap(mode, frameTick = 0) {
  const meta = APK_EYES_BY_MODE[mode];
  if (!meta) return new Bitmap();
  const data = getData();
  // 60Hz tick -> ~12.5 fps animation (5 ticks per frame)
  const frameIdx = Math.floor(Math.max(0, frameTick) / 5) % meta.count;
  const frameOffset = meta.start + frameIdx * 128;
  const bmp = new Bitmap(COLS, ROWS);
  for (let r = 0; r < 16; r++) {
    const rowOff = frameOffset + r * 8;
    const rIdx = r * COLS;
    // Left eye: columns 8..39
    for (let col = 0; col < 32; col++) {
      const b = data[rowOff + (col >> 3)];
      if ((b >> (7 - (col & 7))) & 1) bmp.data[rIdx + 8 + col] = 1;
    }
    // Right eye: columns 56..87
    for (let col = 0; col < 32; col++) {
      const b = data[rowOff + 4 + (col >> 3)];
      if ((b >> (7 - (col & 7))) & 1) bmp.data[rIdx + 56 + col] = 1;
    }
  }
  return bmp;
}
